"""
Unified n=500 analysis for phase-gated compound sparsity (PACS).

Analyses performed:
  1. Median II (low-high) + bootstrap 95% CI (B=10000, percentile method)
  2. Mid-phase null rate per condition
  3. Within-importance paired Cohen's d_z across sparsity levels (D059)
     - imp-vs-rand: Wilcoxon p + median_diff only, NO d_z
  4. Permutation monotonicity test across sparsity gradient
  5. Bonferroni correction on all reported p-values

Input:  profiling_output_{n500_,}bf16_{ds,qw}_{imp,rand}_s{015..030}/profiling_results.json
Output: analysis_output/n500_unified{_dryrun}.json
        analysis_output/n500_unified{_dryrun}.csv  (--csv)
        LaTeX table rows to stdout (--latex)

Constraints:
  D054: median only, no mean
  D059: d_z within-importance only; imp-vs-rand gets Wilcoxon + median_diff
"""

import json
import argparse
import sys
from pathlib import Path
from typing import Optional, List, Dict, Tuple, Any

import numpy as np
from scipy import stats

BASE = Path("/root/autodl-tmp/pacs")

MODEL_MAP = {"deepseek": "ds", "qwen": "qw"}
MASKING_TYPES = ["imp", "rand"]
SPARSITY_LABELS = ["s015", "s020", "s025", "s030"]
SPARSITY_VALUES = {"s015": 0.15, "s020": 0.20, "s025": 0.25, "s030": 0.30}
SPARSITY_KEY_MAP = {"s015": "0.15", "s020": "0.2", "s025": "0.25", "s030": "0.3"}

WITHIN_IMP_PAIRS = [
    ("s015", "s020"),
    ("s020", "s025"),
    ("s025", "s030"),
    ("s015", "s030"),
]

B_BOOT = 10000
SEED = 42
ALPHA = 0.05
N_PERM = 5000


# ── Path / IO ────────────────────────────────────────────────────────

def dir_name(model_short: str, masking: str, slabel: str, n500: bool = True) -> str:
    prefix = "n500_" if n500 else ""
    return f"profiling_output_{prefix}bf16_{model_short}_{masking}_{slabel}"


def load_problems(dirpath: Path) -> Optional[List[dict]]:
    fpath = dirpath / "profiling_results.json"
    if not fpath.exists():
        return None
    with open(fpath) as f:
        data = json.load(f)
    ppi = data.get("per_problem_ii", {})
    keys = list(ppi.keys())
    if not keys:
        return None
    return ppi[keys[0]]


# ── Statistics ────────────────────────────────────────────────────────

def extract_diffs(problems: List[dict], pa: str = "low", pb: str = "high") -> np.ndarray:
    diffs = []
    for p in problems:
        va, vb = p.get(f"ii_{pa}"), p.get(f"ii_{pb}")
        if va is not None and vb is not None:
            diffs.append(va - vb)
    return np.array(diffs)


def bootstrap_median_ci(arr: np.ndarray, B: int = B_BOOT,
                        alpha: float = ALPHA, seed: int = SEED) -> Tuple[float, float]:
    rng = np.random.RandomState(seed)
    n = len(arr)
    medians = np.empty(B)
    for i in range(B):
        medians[i] = np.median(arr[rng.randint(0, n, size=n)])
    lo = float(np.percentile(medians, 100 * alpha / 2))
    hi = float(np.percentile(medians, 100 * (1 - alpha / 2)))
    return lo, hi


def paired_cohens_dz(diffs: np.ndarray) -> float:
    if len(diffs) < 2:
        return float("nan")
    s = np.std(diffs, ddof=1)
    if s == 0:
        return float("nan")
    return float(np.mean(diffs) / s)


def bootstrap_dz_ci(diffs: np.ndarray, B: int = B_BOOT,
                     alpha: float = ALPHA, seed: int = SEED) -> Tuple[float, float]:
    rng = np.random.RandomState(seed)
    n = len(diffs)
    boot = np.empty(B)
    for i in range(B):
        sample = diffs[rng.randint(0, n, size=n)]
        s = sample.std(ddof=1)
        boot[i] = sample.mean() / s if s > 0 else np.nan
    boot = boot[~np.isnan(boot)]
    if len(boot) == 0:
        return float("nan"), float("nan")
    return (float(np.percentile(boot, 100 * alpha / 2)),
            float(np.percentile(boot, 100 * (1 - alpha / 2))))


def interpret_d(d: float) -> str:
    ad = abs(d)
    if ad < 0.2:
        return "negligible"
    elif ad < 0.5:
        return "small"
    elif ad < 0.8:
        return "medium"
    return "large"


def midphase_null_rate(problems: List[dict]) -> Dict[str, Any]:
    total = len(problems)
    null_mid = sum(1 for p in problems if p.get("ii_mid") is None)
    null_low = sum(1 for p in problems if p.get("ii_low") is None)
    null_high = sum(1 for p in problems if p.get("ii_high") is None)
    return {
        "n_total": total,
        "null_mid": null_mid,
        "null_mid_rate": round(null_mid / total, 4) if total > 0 else None,
        "null_low": null_low,
        "null_high": null_high,
    }


def permutation_monotonicity_test(medians_by_sparsity: Dict[str, float],
                                   n_perm: int = N_PERM, seed: int = SEED) -> Dict[str, Any]:
    """Test whether median II diffs are monotonically increasing with sparsity."""
    ordered = sorted(medians_by_sparsity.items(), key=lambda x: SPARSITY_VALUES.get(x[0], 0))
    if len(ordered) < 3:
        return {"error": f"need >=3 sparsity levels, got {len(ordered)}"}

    labels = [o[0] for o in ordered]
    vals = np.array([o[1] for o in ordered])

    diffs_consecutive = np.diff(vals)
    n_increasing = int(np.sum(diffs_consecutive > 0))
    is_monotonic = bool(n_increasing == len(diffs_consecutive))

    observed_stat = float(np.sum(diffs_consecutive))

    rng = np.random.RandomState(seed)
    count = 0
    for _ in range(n_perm):
        perm_vals = rng.permutation(vals)
        perm_stat = float(np.sum(np.diff(perm_vals)))
        if perm_stat >= observed_stat:
            count += 1
    p = (count + 1) / (n_perm + 1)

    return {
        "sparsity_order": labels,
        "medians": vals.tolist(),
        "consecutive_diffs": diffs_consecutive.tolist(),
        "n_increasing_steps": n_increasing,
        "is_monotonic": is_monotonic,
        "sum_gradient_stat": observed_stat,
        "permutation_p": float(p),
        "n_perm": n_perm,
    }


def bonferroni(p: float, n_tests: int) -> float:
    return min(p * n_tests, 1.0)


# ── Per-condition analysis ────────────────────────────────────────────

def analyze_condition(problems: List[dict]) -> Dict[str, Any]:
    diffs = extract_diffs(problems, "low", "high")
    n_valid = len(diffs)
    if n_valid < 5:
        return {"error": f"too few valid: {n_valid}", "n_valid": n_valid}

    med = float(np.median(diffs))
    ci_lo, ci_hi = bootstrap_median_ci(diffs)
    crosses_zero = (ci_lo <= 0 <= ci_hi)

    per_phase = {}
    for ph in ["high", "mid", "low"]:
        vals = [p[f"ii_{ph}"] for p in problems if p.get(f"ii_{ph}") is not None]
        if vals:
            arr = np.array(vals)
            per_phase[ph] = {
                "n": len(arr),
                "median": float(np.median(arr)),
                "iqr": float(np.percentile(arr, 75) - np.percentile(arr, 25)),
            }

    null_info = midphase_null_rate(problems)

    wilcoxon_stat, wilcoxon_p = stats.wilcoxon(diffs, alternative="two-sided")

    return {
        "n_valid": n_valid,
        "median_ii_diff": med,
        "median_ii_diff_ci": [ci_lo, ci_hi],
        "ci_excludes_zero": not crosses_zero,
        "wilcoxon_stat": float(wilcoxon_stat),
        "wilcoxon_p": float(wilcoxon_p),
        "per_phase_median": per_phase,
        "midphase_null": null_info,
    }


# ── Model-level analysis ─────────────────────────────────────────────

def analyze_model(model_name: str, n500: bool = True) -> Dict[str, Any]:
    ms = MODEL_MAP[model_name]
    all_problems = {}
    available = {}

    for masking in MASKING_TYPES:
        for sl in SPARSITY_LABELS:
            key = f"{masking}_{sl}"
            dname = dir_name(ms, masking, sl, n500=n500)
            dpath = BASE / dname
            problems = load_problems(dpath)
            if problems is not None:
                all_problems[key] = problems
                available[key] = len(problems)
            else:
                available[key] = 0

    # 1. Per-condition: median II diff + CI + midphase null
    cond_out = {}
    for key, problems in all_problems.items():
        cond_out[key] = analyze_condition(problems)

    # 2. Within-importance d_z (D059: only imp pairs)
    dz_importance = {}
    for sl_a, sl_b in WITHIN_IMP_PAIRS:
        pair_key = f"{sl_a}_vs_{sl_b}"
        key_a = f"imp_{sl_a}"
        key_b = f"imp_{sl_b}"
        if key_a not in all_problems or key_b not in all_problems:
            dz_importance[pair_key] = {"error": "missing data"}
            continue

        probs_a = all_problems[key_a]
        probs_b = all_problems[key_b]
        diffs_a = extract_diffs(probs_a, "low", "high")
        diffs_b = extract_diffs(probs_b, "low", "high")

        n_paired = min(len(diffs_a), len(diffs_b))
        if n_paired < 5:
            dz_importance[pair_key] = {"error": f"too few paired: {n_paired}"}
            continue

        paired_diffs = diffs_a[:n_paired] - diffs_b[:n_paired]
        dz = paired_cohens_dz(paired_diffs)
        dz_ci = bootstrap_dz_ci(paired_diffs)
        w_stat, w_p = stats.wilcoxon(paired_diffs, alternative="two-sided")

        dz_importance[pair_key] = {
            "d_z": dz,
            "d_z_ci": list(dz_ci),
            "interpretation": interpret_d(dz),
            "n_paired": n_paired,
            "median_diff": float(np.median(paired_diffs)),
            "wilcoxon_stat": float(w_stat),
            "wilcoxon_p": float(w_p),
        }

    # 3. Random within-pairs: Wilcoxon + median_diff only (D059: no d_z)
    rand_comparisons = {}
    for sl_a, sl_b in WITHIN_IMP_PAIRS:
        pair_key = f"{sl_a}_vs_{sl_b}"
        key_a = f"rand_{sl_a}"
        key_b = f"rand_{sl_b}"
        if key_a not in all_problems or key_b not in all_problems:
            rand_comparisons[pair_key] = {"error": "missing data"}
            continue

        diffs_a = extract_diffs(all_problems[key_a], "low", "high")
        diffs_b = extract_diffs(all_problems[key_b], "low", "high")
        n_paired = min(len(diffs_a), len(diffs_b))
        if n_paired < 5:
            rand_comparisons[pair_key] = {"error": f"too few paired: {n_paired}"}
            continue

        paired_diffs = diffs_a[:n_paired] - diffs_b[:n_paired]
        w_stat, w_p = stats.wilcoxon(paired_diffs, alternative="two-sided")
        rand_comparisons[pair_key] = {
            "median_diff": float(np.median(paired_diffs)),
            "wilcoxon_stat": float(w_stat),
            "wilcoxon_p": float(w_p),
            "n_paired": n_paired,
        }

    # 4. Imp-vs-rand comparisons: Wilcoxon + median_diff (D059: no d_z)
    imp_vs_rand = {}
    for sl in SPARSITY_LABELS:
        key_imp = f"imp_{sl}"
        key_rand = f"rand_{sl}"
        if key_imp not in all_problems or key_rand not in all_problems:
            imp_vs_rand[sl] = {"error": "missing data"}
            continue

        diffs_imp = extract_diffs(all_problems[key_imp], "low", "high")
        diffs_rand = extract_diffs(all_problems[key_rand], "low", "high")
        n_paired = min(len(diffs_imp), len(diffs_rand))
        if n_paired < 5:
            imp_vs_rand[sl] = {"error": f"too few paired: {n_paired}"}
            continue

        paired_diffs = diffs_imp[:n_paired] - diffs_rand[:n_paired]
        w_stat, w_p = stats.wilcoxon(paired_diffs, alternative="two-sided")
        imp_vs_rand[sl] = {
            "median_diff": float(np.median(paired_diffs)),
            "wilcoxon_stat": float(w_stat),
            "wilcoxon_p": float(w_p),
            "n_paired": n_paired,
        }

    # 5. Permutation monotonicity test
    dose_imp = {}
    dose_rand = {}
    for masking, dose_dict in [("imp", dose_imp), ("rand", dose_rand)]:
        medians = {}
        for sl in SPARSITY_LABELS:
            key = f"{masking}_{sl}"
            if key in cond_out and "error" not in cond_out[key]:
                medians[sl] = cond_out[key]["median_ii_diff"]
        if len(medians) >= 3:
            dose_dict.update(permutation_monotonicity_test(medians))
        else:
            dose_dict["error"] = f"need >=3 levels, got {len(medians)}"

    # 6. Bonferroni correction
    all_p_values = []
    p_registry = []

    for key, c in cond_out.items():
        if "wilcoxon_p" in c:
            p_registry.append(("condition", key, "wilcoxon_p"))
            all_p_values.append(c["wilcoxon_p"])

    for pair_key, v in dz_importance.items():
        if "wilcoxon_p" in v:
            p_registry.append(("dz_imp", pair_key, "wilcoxon_p"))
            all_p_values.append(v["wilcoxon_p"])

    for pair_key, v in rand_comparisons.items():
        if "wilcoxon_p" in v:
            p_registry.append(("rand_within", pair_key, "wilcoxon_p"))
            all_p_values.append(v["wilcoxon_p"])

    for sl, v in imp_vs_rand.items():
        if "wilcoxon_p" in v:
            p_registry.append(("imp_vs_rand", sl, "wilcoxon_p"))
            all_p_values.append(v["wilcoxon_p"])

    n_tests = len(all_p_values)

    for i, (category, key, field) in enumerate(p_registry):
        raw_p = all_p_values[i]
        corrected = bonferroni(raw_p, n_tests)
        if category == "condition":
            cond_out[key]["bonferroni_p"] = corrected
            cond_out[key]["n_tests_bonferroni"] = n_tests
        elif category == "dz_imp":
            dz_importance[key]["bonferroni_p"] = corrected
        elif category == "rand_within":
            rand_comparisons[key]["bonferroni_p"] = corrected
        elif category == "imp_vs_rand":
            imp_vs_rand[key]["bonferroni_p"] = corrected

    return {
        "conditions": cond_out,
        "within_dz_importance": dz_importance,
        "within_rand_comparisons": rand_comparisons,
        "imp_vs_rand": imp_vs_rand,
        "dose_response": {
            "importance": dose_imp,
            "random": dose_rand,
        },
        "bonferroni_n_tests": n_tests,
        "available_conditions": available,
    }


# ── LaTeX output ──────────────────────────────────────────────────────

def fmt(v: float, decimals: int = 4) -> str:
    return f"{v:.{decimals}f}"


def fmt_p(p: float) -> str:
    if p < 0.001:
        return "$<$0.001"
    return f"{p:.3f}"


def latex_output(full_output: dict):
    print("\n" + "=" * 70)
    print("LATEX TABLE ROWS")
    print("=" * 70)

    # Table 1: Per-condition median II diff + CI
    print("\n% Table: Median II (low-high) by condition")
    print("% Model & Masking & Sparsity & n & Median & CI_low & CI_high & p & p_bonf \\\\")
    for m_name, m_data in full_output["models"].items():
        for masking in MASKING_TYPES:
            for sl in SPARSITY_LABELS:
                key = f"{masking}_{sl}"
                c = m_data.get("conditions", {}).get(key, {})
                if "error" in c:
                    continue
                s_val = SPARSITY_VALUES[sl]
                mask_label = "Importance" if masking == "imp" else "Random"
                ci = c["median_ii_diff_ci"]
                p_raw = c["wilcoxon_p"]
                p_bonf = c.get("bonferroni_p", p_raw)
                null_mid = c.get("midphase_null", {}).get("null_mid_rate", "")
                print(f"{m_name.capitalize()} & {mask_label} & {s_val:.0%} & "
                      f"{c['n_valid']} & {fmt(c['median_ii_diff'])} & "
                      f"{fmt(ci[0])} & {fmt(ci[1])} & "
                      f"{fmt_p(p_raw)} & {fmt_p(p_bonf)} \\\\")

    # Table 2: Mid-phase null rates
    print("\n% Table: Mid-phase null rates")
    print("% Model & Masking & Sparsity & n_total & null_mid & null_rate \\\\")
    for m_name, m_data in full_output["models"].items():
        for masking in MASKING_TYPES:
            for sl in SPARSITY_LABELS:
                key = f"{masking}_{sl}"
                c = m_data.get("conditions", {}).get(key, {})
                null_info = c.get("midphase_null", {})
                if not null_info or "n_total" not in null_info:
                    continue
                mask_label = "Importance" if masking == "imp" else "Random"
                s_val = SPARSITY_VALUES[sl]
                rate = null_info["null_mid_rate"]
                rate_str = f"{rate:.1%}" if rate is not None else "N/A"
                print(f"{m_name.capitalize()} & {mask_label} & {s_val:.0%} & "
                      f"{null_info['n_total']} & {null_info['null_mid']} & "
                      f"{rate_str} \\\\")

    # Table 3: Within-importance d_z
    print("\n% Table: Within-importance paired d_z (D059)")
    print("% Model & Pair & d_z & CI_low & CI_high & Interp & p & p_bonf \\\\")
    for m_name, m_data in full_output["models"].items():
        dz_data = m_data.get("within_dz_importance", {})
        for pair_key, v in dz_data.items():
            if "error" in v:
                continue
            p_bonf = v.get("bonferroni_p", v["wilcoxon_p"])
            print(f"{m_name.capitalize()} & {pair_key} & "
                  f"{fmt(v['d_z'])} & {fmt(v['d_z_ci'][0])} & {fmt(v['d_z_ci'][1])} & "
                  f"{v['interpretation']} & {fmt_p(v['wilcoxon_p'])} & {fmt_p(p_bonf)} \\\\")

    # Table 4: Random within-sparsity (Wilcoxon only, no d_z per D059)
    print("\n% Table: Random within-sparsity (Wilcoxon + median_diff, no d_z)")
    print("% Model & Pair & median_diff & p & p_bonf \\\\")
    for m_name, m_data in full_output["models"].items():
        rand_data = m_data.get("within_rand_comparisons", {})
        for pair_key, v in rand_data.items():
            if "error" in v:
                continue
            p_bonf = v.get("bonferroni_p", v["wilcoxon_p"])
            print(f"{m_name.capitalize()} & {pair_key} & "
                  f"{fmt(v['median_diff'])} & {fmt_p(v['wilcoxon_p'])} & {fmt_p(p_bonf)} \\\\")

    # Table 5: Imp vs rand
    print("\n% Table: Importance vs Random (Wilcoxon + median_diff, no d_z)")
    print("% Model & Sparsity & median_diff & p & p_bonf \\\\")
    for m_name, m_data in full_output["models"].items():
        ivr = m_data.get("imp_vs_rand", {})
        for sl in SPARSITY_LABELS:
            v = ivr.get(sl, {})
            if "error" in v:
                continue
            s_val = SPARSITY_VALUES[sl]
            p_bonf = v.get("bonferroni_p", v["wilcoxon_p"])
            print(f"{m_name.capitalize()} & {s_val:.0%} & "
                  f"{fmt(v['median_diff'])} & {fmt_p(v['wilcoxon_p'])} & {fmt_p(p_bonf)} \\\\")

    # Table 6: Dose-response monotonicity
    print("\n% Table: Dose-response permutation monotonicity test")
    print("% Model & Masking & rho_sum & monotonic & perm_p \\\\")
    for m_name, m_data in full_output["models"].items():
        for scope in ["importance", "random"]:
            dr = m_data.get("dose_response", {}).get(scope, {})
            if "error" in dr:
                continue
            mask_label = "Importance" if scope == "importance" else "Random"
            print(f"{m_name.capitalize()} & {mask_label} & "
                  f"{fmt(dr['sum_gradient_stat'])} & "
                  f"{'Yes' if dr['is_monotonic'] else 'No'} & "
                  f"{fmt_p(dr['permutation_p'])} \\\\")


# ── Serialization ─────────────────────────────────────────────────────

def sanitize(obj):
    if isinstance(obj, dict):
        return {k: sanitize(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [sanitize(v) for v in obj]
    elif isinstance(obj, (np.integer,)):
        return int(obj)
    elif isinstance(obj, (np.floating,)):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, (np.bool_,)):
        return bool(obj)
    return obj


# ── Main ──────────────────────────────────────────────────────────────

def main():
    parser = argparse.ArgumentParser(description="Unified n=500 PACS analysis")
    parser.add_argument("--model", choices=["deepseek", "qwen", "all"], default="all")
    parser.add_argument("--dry-run", action="store_true", help="Use n=50 data")
    parser.add_argument("--csv", action="store_true", help="Also output CSV")
    parser.add_argument("--latex", action="store_true", help="Print LaTeX table rows")
    args = parser.parse_args()

    n500 = not args.dry_run
    models = list(MODEL_MAP.keys()) if args.model == "all" else [args.model]

    full_output = {
        "meta": {
            "analysis": "n500_unified_v2",
            "data": "n500" if n500 else "n50_dryrun",
            "bootstrap_B": B_BOOT,
            "alpha": ALPHA,
            "permutation_N": N_PERM,
            "seed": SEED,
            "statistic": "median (D054)",
            "dz_scope": "within-importance only (D059)",
            "imp_vs_rand_scope": "Wilcoxon + median_diff only (D059)",
        },
        "models": {},
    }

    for m in models:
        print(f"\n{'='*70}")
        print(f"  {m.upper()}")
        print(f"{'='*70}")
        result = analyze_model(m, n500=n500)
        full_output["models"][m] = sanitize(result)

        # Print summary
        for key, c in result["conditions"].items():
            if "error" in c:
                print(f"  {key}: {c['error']}")
            else:
                ci = c["median_ii_diff_ci"]
                p_bonf = c.get("bonferroni_p", c["wilcoxon_p"])
                null_rate = c.get("midphase_null", {}).get("null_mid_rate", "?")
                print(f"  {key}: median={c['median_ii_diff']:+.4f} "
                      f"CI=[{ci[0]:.4f},{ci[1]:.4f}] "
                      f"p_bonf={p_bonf:.4f} "
                      f"mid_null={null_rate}")

        print(f"\n  Within-imp d_z:")
        for pk, v in result["within_dz_importance"].items():
            if "error" in v:
                print(f"    {pk}: {v['error']}")
            else:
                print(f"    {pk}: d_z={v['d_z']:+.3f} [{v['d_z_ci'][0]:.3f},{v['d_z_ci'][1]:.3f}] "
                      f"({v['interpretation']})")

        print(f"\n  Imp-vs-rand:")
        for sl, v in result["imp_vs_rand"].items():
            if "error" in v:
                print(f"    {sl}: {v['error']}")
            else:
                print(f"    {sl}: median_diff={v['median_diff']:+.4f} "
                      f"p_bonf={v.get('bonferroni_p', v['wilcoxon_p']):.4f}")

        print(f"\n  Dose-response:")
        for scope in ["importance", "random"]:
            dr = result["dose_response"].get(scope, {})
            if "error" in dr:
                print(f"    {scope}: {dr['error']}")
            else:
                print(f"    {scope}: monotonic={dr['is_monotonic']} "
                      f"gradient_sum={dr['sum_gradient_stat']:.4f} "
                      f"perm_p={dr['permutation_p']:.4f}")

    # Save JSON
    out_dir = BASE / "analysis_output"
    out_dir.mkdir(exist_ok=True)
    suffix = "_dryrun" if args.dry_run else ""

    json_path = out_dir / f"n500_unified{suffix}.json"
    with open(json_path, "w") as f:
        json.dump(full_output, f, indent=2)
    print(f"\nSaved: {json_path}")

    # CSV
    if args.csv:
        csv_path = out_dir / f"n500_unified{suffix}.csv"
        with open(csv_path, "w") as f:
            f.write("model,masking,sparsity,n,median_ii_diff,ci_lo,ci_hi,"
                    "ci_excludes_zero,wilcoxon_p,bonferroni_p,mid_null_rate\n")
            for m_name, m_data in full_output["models"].items():
                for key, c in m_data.get("conditions", {}).items():
                    if "error" in c:
                        continue
                    parts = key.split("_")
                    masking, sl = parts[0], parts[1]
                    ci = c["median_ii_diff_ci"]
                    null_rate = c.get("midphase_null", {}).get("null_mid_rate", "")
                    f.write(f"{m_name},{masking},{sl},{c['n_valid']},"
                            f"{c['median_ii_diff']},{ci[0]},{ci[1]},"
                            f"{c['ci_excludes_zero']},{c['wilcoxon_p']},"
                            f"{c.get('bonferroni_p', '')},{null_rate}\n")

            f.write("\n# Within-importance d_z\n")
            f.write("model,pair,d_z,dz_ci_lo,dz_ci_hi,interpretation,wilcoxon_p,bonferroni_p,n_paired\n")
            for m_name, m_data in full_output["models"].items():
                for pk, v in m_data.get("within_dz_importance", {}).items():
                    if "error" in v:
                        continue
                    f.write(f"{m_name},{pk},{v['d_z']},"
                            f"{v['d_z_ci'][0]},{v['d_z_ci'][1]},"
                            f"{v['interpretation']},{v['wilcoxon_p']},"
                            f"{v.get('bonferroni_p', '')},{v['n_paired']}\n")

            f.write("\n# Imp vs Rand (Wilcoxon only)\n")
            f.write("model,sparsity,median_diff,wilcoxon_p,bonferroni_p,n_paired\n")
            for m_name, m_data in full_output["models"].items():
                for sl, v in m_data.get("imp_vs_rand", {}).items():
                    if "error" in v:
                        continue
                    f.write(f"{m_name},{sl},{v['median_diff']},"
                            f"{v['wilcoxon_p']},{v.get('bonferroni_p', '')},"
                            f"{v['n_paired']}\n")
        print(f"Saved: {csv_path}")

    # LaTeX
    if args.latex:
        latex_output(full_output)

    print("\nDone.")


if __name__ == "__main__":
    main()
